// GET /api/v1/permissions/catalog: the permission tree, generated by the backend from its registered modules and screens.
export type PermissionCatalogActionResponse = {
  permissionCode: string;
  actionCode: string;
  displayName: string;
  // Held by the company owner by role; it cannot be given to anyone else.
  isOwnerOnly?: boolean;
};

export type PermissionCatalogScreenResponse = {
  screenCode: string;
  displayName: string;
  subGroupCode: string | null;
  actions: PermissionCatalogActionResponse[];
};

export type PermissionCatalogModuleResponse = {
  moduleCode: string;
  displayName: string;
  screens: PermissionCatalogScreenResponse[];
};

export type PermissionCatalogResponse = { modules: PermissionCatalogModuleResponse[] };

// How a route or a UI block names the permissions it needs.
export type PermissionRequirement<TPermissionCode extends string = string> = {
  mode: "any" | "all";
  permissionCodes: readonly TPermissionCode[];
};
